CREATE OR REPLACE FUNCTION public.academic_year_show()\n RETURNS TABLE(id integer, academic character varying, started date, ended date, state character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n\n    RETURN QUERY\n    SELECT\n        ac.a_y_id,\n        ac.academic_name,\n        ac.started,\n        ac.ended,\n        ac.state\n    FROM academic_year ac;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.account_transfer_show(br_id_sp integer)\n RETURNS TABLE(id integer, "account from" character varying, "account TO" character varying, amount numeric, description character varying, users character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n        SELECT act.acc_tr_id AS ID,  ac1.acc_name AS "account from",  ac2.acc_name AS "account TO",  act.amount,  act.description,  u.username AS "Users",  act.reg_date\n        FROM account_transfer act\n        JOIN accounts ac1 ON ac1.acc_id = act.from_acc\n        JOIN accounts ac2 ON ac2.acc_id = act.to_acc\n        JOIN user_branch ub ON ub.u_br_id = act.u_br_id\n        JOIN branch b ON b.br_id = ub.br_id\n        JOIN users u ON u.usr_id = ub.usr_id;\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\n        SELECT act.acc_tr_id AS ID,  ac1.acc_name AS "account from",  ac2.acc_name AS "account TO",  act.amount,  act.description,  u.username AS "Users",  act.reg_date\n        FROM account_transfer act\n        JOIN accounts ac1 ON ac1.acc_id = act.from_acc\n        JOIN accounts ac2 ON ac2.acc_id = act.to_acc\n        JOIN user_branch ub ON ub.u_br_id = act.u_br_id\n        JOIN branch b ON b.br_id = ub.br_id\n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE b.br_id = br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.account_type_show(br_id_sp integer)\n RETURNS TABLE(id integer, type character varying, category character varying, state character varying, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                select act.ac_ty_id ID , act.type,acc.type "category", act.state , u.username  from  account_type act \n\t\t\tJOIN acc_category acc on acc.ac_cat_id = act.ac_cat_id\n\t\t\tJOIN user_branch ub on ub.u_br_id = act.u_br_id\n\t\t\tjoin branch  b on b.br_id = ub.br_id\n\t\t\tJOIN users u on u.usr_id = ub.usr_id;\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\n\t\t\n        select act.ac_ty_id ID , act.type,acc.type "category", act.state  category, u.username  from  account_type act \n\t\t\tJOIN acc_category acc on acc.ac_cat_id = act.ac_cat_id\n\t\t\tJOIN user_branch ub on ub.u_br_id = act.u_br_id\n\t\t\tjoin branch  b on b.br_id = ub.br_id\n\t\t\tJOIN users u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.accounts_show(br_id_sp integer)\n RETURNS TABLE(id integer, accounts character varying, institution character varying, balance numeric, br_name character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nDECLARE br_name_sp TEXT;\nBEGIN\nselect b.br_name into br_name_sp from branch b where b.br_id = br_id_sp;\nIF br_name_sp='All' then \n RETURN QUERY\n\tSELECT a.acc_id AS ID, \n           a.acc_name AS accounts, \t\n           a.institution, \n           a.balance, \n           b.br_name, \n           u.username,\n\t\t   a.reg_date\n    FROM accounts a\n    JOIN branch b ON b.br_id = a.acc_id\n    JOIN user_branch ub ON b.br_id = ub.u_br_id\n    JOIN users u ON u.usr_id = ub.u_br_id;\n\n\tELSE\n    RETURN QUERY\n\t\n    SELECT a.acc_id AS ID, \n           a.acc_name AS accounts, \t\n           a.institution, \n           a.balance, \n           b.br_name, \n           u.username,\n\t\t   a.reg_date\n    FROM accounts a\n    JOIN branch b ON b.br_id = a.acc_id\n    JOIN user_branch ub ON b.br_id = ub.u_br_id\n    JOIN users u ON u.usr_id = ub.u_br_id\n    WHERE b.br_id = br_id_sp;\n\tend if;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.activity_type_show(p_branch_id integer)\n RETURNS TABLE(ac_id integer, type character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n   \n        RETURN QUERY\n        select a.ac_id ID,a.type from Activity_type a;\n \nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.asset_order_show(br_id_sp integer)\n RETURNS TABLE(id integer, "Name" character varying, tell character varying, sex character varying, type character varying, description character varying, state character varying, number character varying, freight character varying, "Oder Date" timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                  select  ar.as_or_id ID , p.p_name "Name",p.tel "tell" , p.sex ,  ty.type_name "type" , ar.description , ar.state , ar.po_number "number" , ar.freight , ar.or_date "Oder Date" ,  u.username from  asset_order ar\n\t\t\tjoin types ty on ty.ty_id = ar.ty_id \n\t\t\tjoin people p on p.p_id = ar.p_id\n\t\t\tJOIN user_branch ub on ub.u_br_id = ar.u_br_id\n\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\tJOIN users u on u.usr_id = ub.usr_id;\n\t\t\t\t\n\t\t\t\t\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n        select  ar.as_or_id ID , p.p_name "Name",p.tel "tell" , p.sex ,  ty.type_name "type" , ar.description , ar.state , ar.po_number "number" , ar.freight , ar.or_date "Oder Date" ,  u.username from  asset_order ar\n\t\t\tjoin types ty on ty.ty_id = ar.ty_id \n\t\t\tjoin people p on p.p_id = ar.p_id\n\t\t\tJOIN user_branch ub on ub.u_br_id = ar.u_br_id\n\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\tJOIN users u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.asset_payment_show(br_id_sp integer)\n RETURNS TABLE(id integer, name character varying, tell character varying, method character varying, amount numeric, account character varying, description character varying, num character varying, "payment Date" timestamp without time zone, "Date" timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n           select ap.p_id ID , p.p_name "name" , p.tel "tell" , mm.method ,ap.amount , ac.acc_name "account" , ap.description , ap.num , ap.pay_date "payment Date" , ap.reg_date "Date" , u.username from asset_payment ap\n\t\t\t\t\tjoin money_methods mm on mm.mm_id = ap.mm_id\n\t\t\t\t\tjoin people p on p.p_id = ap.p_id \n\t\t\t\t\tjoin accounts ac on ac.acc_id = ap.acc_id\n\t\t\t\t\tjoin user_branch ub on ub.u_br_id = ap.u_br_id\n\t\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\t\tjoin users u on u.usr_id = ub.usr_id;\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n       select ap.p_id ID , p.p_name "name" , p.tel "tell" , mm.method ,ap.amount , ac.acc_name "account" , ap.description , ap.num , ap.pay_date "payment Date" , ap.reg_date "Date" , u.username from asset_payment ap\n\t\t\t\tjoin money_methods mm on mm.mm_id = ap.mm_id\n\t\t\t\tjoin people p on p.p_id = ap.p_id \n\t\t\t\tjoin accounts ac on ac.acc_id = ap.acc_id\n\t\t\t\tjoin user_branch ub on ub.u_br_id = ap.u_br_id\n\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\tjoin users u on u.usr_id = ub.usr_id\n\t\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.asset_transaction_show(br_id_sp integer)\n RETURNS TABLE(id integer, "Name" character varying, tell character varying, description character varying, qty character varying, price numeric, date timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                 Select ast.as_tr_id ID , p.p_name "Name",p.tel "tell",ar.description,  ast.qty , ast.price , ast.reg_date "Date", u.username from asset_Transaction ast \n\t\t\tJOIN asset_order ar on ar.as_or_id = ast.as_or_id\n\t\t\tjoin people p on p.p_id = ar.p_id \n\t\t\tJOIN assets ass on ass.ass_id = ast.ass_id\n\t\t\tJOIN  user_branch ub on ub.u_br_id = ast.u_br_id\n\t\t\tJOIN branch b on b.br_id = ub.br_id\n\t\t\tjoin users u on u.usr_id = ub.usr_id;\n\t\t\t\t\n\t\t\t\t\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n       Select ast.as_tr_id ID , p.p_name "Name",p.tel "tell",ar.description,  ast.qty , ast.price , ast.reg_date "Date", u.username from asset_Transaction ast \n\t\t\tJOIN asset_order ar on ar.as_or_id = ast.as_or_id\n\t\t\tjoin people p on p.p_id = ar.p_id \n\t\t\tJOIN assets ass on ass.ass_id = ast.ass_id\n\t\t\tJOIN  user_branch ub on ub.u_br_id = ast.u_br_id\n\t\t\tJOIN branch b on b.br_id = ub.br_id\n\t\t\tjoin users u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.assets_show(br_id_sp integer)\n RETURNS TABLE(id integer, description character varying, balance numeric, amount numeric, dep_amount character varying, date timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n           select ass.ac_ty_id ID, Description, balance , amount , dep_amount , ass.reg_date Date, u.username from  assets ass\n\t\t\t\tJOIN user_branch ub on ub.u_br_id = ass.u_br_id\n\t\t\t\tJOIN branch b on b.br_id = ub.br_id\n\t\t\t\tJOIN users  u on u.usr_id = ub.usr_id;\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n        select ass.ac_ty_id ID, Description, balance , amount , dep_amount , ass.reg_date Date, u.username from  assets ass\n\t\tJOIN user_branch ub on ub.u_br_id = ass.u_br_id\n\t\tJOIN branch b on b.br_id = ub.br_id\n\t\tJOIN users  u on u.usr_id = ub.usr_id\n\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.assign_class_exam_show(p_branch_id integer)\n RETURNS TABLE(a_c_ex integer, exam character varying, class character varying, batch_name character varying, state character varying, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all records\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT \n            ass.a_c_ex,\n            e.exam,\n            cl.class,\n            b.batch_name,\n            ass.state,\n            u.username,\n            DATE(ass.reg_date)  -- Cast to DATE if it's timestamp\n        FROM assign_class_exam ass \n        JOIN class cl ON ass.cl_id = cl.cl_id \n        JOIN exam_reg er ON er.ex_reg_id = ass.er_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN batch b ON b.b_id = ass.b_id \n        JOIN user_branch ub ON ub.u_br_id = ass.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        ORDER BY ass.a_c_ex;\n\n    ELSE\n        -- Return records for specific branch\n        RETURN QUERY\n        SELECT \n            ass.a_c_ex,\n            e.exam,\n            cl.class,\n            b.batch_name,\n            ass.state,\n            u.username,\n            DATE(ass.reg_date)  -- Cast to DATE if it's timestamp\n        FROM assign_class_exam ass \n        JOIN class cl ON ass.cl_id = cl.cl_id \n        JOIN exam_reg er ON er.ex_reg_id = ass.er_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN batch b ON b.b_id = ass.b_id \n        JOIN user_branch ub ON ub.u_br_id = ass.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY ass.a_c_ex;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.assign_student_room_show(p_branch_id integer)\n RETURNS TABLE(ass_std_ro_id integer, p_name character varying, class character varying, room_name character varying, exam character varying, serial_num integer, shift character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            asr.ass_std_ro_id,\n            p.p_name Student,\n            cl.class,\n            r.room_name,\n            e.exam,\n            asr.serial_num,\n            sh.shift,\n            u.username,\n            asr.reg_date\n        FROM assign_student_room asr\n        JOIN student_class sc ON asr.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n\t\tjoin people p on s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN rooms r ON r.r_id = asr.ro_id\n        JOIN exam_reg er ON asr.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN shift sh ON asr.sh_id = sh.sh_id\n        JOIN user_branch ub ON asr.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY asr.ass_std_ro_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            asr.ass_std_ro_id,\n            p.p_name Student,\n            cl.class,\n            r.room_name,\n            e.exam,\n            asr.serial_num,\n            sh.shift,\n            u.username,\n            asr.reg_date\n        FROM assign_student_room asr\n        JOIN student_class sc ON asr.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n\t\tjoin people p on s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN rooms r ON r.r_id = asr.ro_id\n        JOIN exam_reg er ON asr.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN shift sh ON asr.sh_id = sh.sh_id\n        JOIN user_branch ub ON asr.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY asr.ass_std_ro_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.assign_teacher_room_show(p_branch_id integer)\n RETURNS TABLE(ass_t_ro_id integer, teacher_name character varying, room_name character varying, day character varying, period character varying, exam character varying, shift character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            atr.ass_t_ro_id,\n            p.p_name,\n            r.room_name,\n            d.day,\n            pr.period,\n            e.exam,\n            sh.shift,\n            u.username,\n            atr.reg_date\n        FROM assign_teacher_room atr\n        JOIN rooms r ON r.r_id = atr.ro_id\n        JOIN employee emp ON atr.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN day d ON atr.d_id = d.d_id\n        JOIN period pr ON atr.pe_id = pr.pr_id\n        JOIN exam_reg er ON atr.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN shift sh ON atr.sh_id = sh.sh_id\n        JOIN user_branch ub ON atr.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY atr.ass_t_ro_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            atr.ass_t_ro_id,\n            p.p_name,\n            r.room_name,\n            d.day,\n            pr.period,\n            e.exam,\n            sh.shift,\n            u.username,\n            atr.reg_date\n        FROM assign_teacher_room atr\n        JOIN rooms r ON r.r_id = atr.ro_id\n        JOIN employee emp ON atr.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN day d ON atr.d_id = d.d_id\n        JOIN period pr ON atr.pe_id = pr.pr_id\n        JOIN exam_reg er ON atr.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN shift sh ON atr.sh_id = sh.sh_id\n        JOIN user_branch ub ON atr.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY atr.ass_t_ro_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.branch_show(p_branch_id integer)\n RETURNS TABLE(br_id integer, br_name character varying, manager character varying, manager_tel character varying, contacts text, logo_image text, banner_image text, fg text, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        br.br_id,\n        br.br_name,\n        br.manager,\n        br.manager_tel,\n        br.contacts,\n        br.logo_image,\n        br.banner_image,\n        br.fg,\n        br.reg_date\n    FROM branch br\n    WHERE br.br_id = p_branch_id;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.certificate_show(p_branch_id integer)\n RETURNS TABLE(crt_id integer, serial_number character varying, person_name character varying, description text, issue_date date, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            c.crt_id,\n            c.serial_number,\n            p.p_name,\n            c.description,\n            c.ishue_date,\n            u.username,\n            c.reg_date\n        FROM certificate c\n        JOIN people p ON c.p_id = p.p_id\n        JOIN user_branch ub ON c.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY c.crt_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            c.crt_id,\n            c.serial_number,\n            p.p_name,\n            c.description,\n            c.ishue_date,\n            u.username,\n            c.reg_date\n        FROM certificate c\n        JOIN people p ON c.p_id = p.p_id\n        JOIN user_branch ub ON c.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY c.crt_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.class_formaster_show(p_branch_id integer, p_academic_year integer)\n RETURNS TABLE(c_f_id integer, person_name character varying, student_name character varying, reg_date date, username character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Return class form master details for a specific branch and academic year\n    RETURN QUERY\n    SELECT \n        cf.c_f_id,\n        p1.p_name AS person_name,  -- Employee name from people table\n        p2.p_name AS student_name, -- Student name from people table\n        cf.reg_date,\n        u.username\n    FROM \n        class_formaster cf\n    JOIN \n        class c ON cf.cl_id = c.cl_id\n    JOIN \n        employee em ON em.emp_id = cf.emp_id\n    JOIN \n        people p1 ON p1.p_id = em.p_id  -- Employee's personal information\n    JOIN \n        student s ON cf.std_id = s.std_id\n    JOIN \n        people p2 ON p2.p_id = s.p_id  -- Student's personal information\n    JOIN \n        user_branch ub ON ub.u_br_id = cf.u_br_id\n    JOIN \n        users u ON u.usr_id = ub.usr_id\n    WHERE \n        ub.br_id = p_branch_id  -- Filter by branch ID\n        AND cf.a_y_id = p_academic_year  -- Filter by academic year\n    ORDER BY \n        cf.c_f_id;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.class_show(p_branch_id integer)\n RETURNS TABLE(cl_id integer, class_name character varying, shift_name character varying, level_name character varying, gr_id integer)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all classes\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT\n            cl.cl_id,\n            cl.class,\n            sh.shift,\n            l.level,\n            cl.gr_id\n        FROM class cl\n        JOIN shift sh ON cl.sh_id = sh.sh_id\n        JOIN levels l ON cl.lev_id = l.lev_id\n        ORDER BY cl.cl_id;\n\n    ELSE\n        -- Return classes for a specific branch\n        RETURN QUERY\n        SELECT\n            cl.cl_id,\n            cl.class,\n            sh.shift,\n            l.level,\n            cl.gr_id\n        FROM class cl\n        JOIN shift sh ON cl.sh_id = sh.sh_id\n        JOIN levels l ON cl.lev_id = l.lev_id\n        JOIN branch br ON cl.br_id = br.br_id\n        WHERE cl.br_id = p_branch_id\n        ORDER BY cl.cl_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.closing_show(br_id_sp integer)\n RETURNS TABLE(id integer, "start date" timestamp without time zone, "close date" timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n           select  cl.cl_id ID, start_date "start date" , close_date "close date" , u.username from closing cl\n\t\t\t\t\tjoin user_branch ub on ub.u_br_id = cl.u_br_id\n\t\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\t\tjoin users u on u.usr_id = ub.usr_id;\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n       select  cl.cl_id ID, start_date "start date" , close_date "close date" , u.username from closing cl\n\t\t\t\tjoin user_branch ub on ub.u_br_id = cl.u_br_id\n\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\tjoin users u on u.usr_id = ub.usr_id\n\t\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.complain_show(p_branch_id integer)\n RETURNS TABLE(com_id integer, complainant_name character varying, phone character varying, complaint text, state character varying, handled_by character varying, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            c.com_id,\n            c.name,\n            c.phone,\n            c.cabasho,\n            c.state,\n            c.comp_username,\n            u.username,\n            c.reg_date\n        FROM complain c\n        JOIN user_branch ub ON c.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY c.com_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            c.com_id,\n            c.name,\n            c.phone,\n            c.cabasho,\n            c.state,\n            c.comp_username,\n            u.username,\n            c.reg_date\n        FROM complain c\n        JOIN user_branch ub ON c.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY c.com_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.depriciation_account_show(br_id_sp integer)\n RETURNS TABLE(id integer, description character varying, amount numeric, date timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n          select  da.ass_id ID, ass.description , da.amount , da.reg_date Date, u.username from  depriciation_account da\n\t\t\t\tJOIN assets ass on ass.ass_id = da.ass_id\n\t\t\t\tJOIN user_branch ub on ub.u_br_id = da.u_br_id\n\t\t\t\tJOIN branch b on b.br_id = ub.br_id\n\t\t\t\tjoin users u on u.usr_id = ub.usr_id;\n\t\t\t\t\n\t\t\t\t\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n        select  da.ass_id ID, ass.description , da.amount , da.reg_date Date, u.username from  depriciation_account da\n\t\t\tJOIN assets ass on ass.ass_id = da.ass_id\n\t\t\tJOIN user_branch ub on ub.u_br_id = da.u_br_id\n\t\t\tJOIN branch b on b.br_id = ub.br_id\n\t\t\tjoin users u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.employee_attendance_show(p_branch_id integer)\n RETURNS TABLE(emp_att_id integer, employee_name character varying, scheduled_time_in time without time zone, scheduled_time_out time without time zone, actual_time_in time without time zone, actual_time_out time without time zone, status character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            ea.emp_att_id,\n            p.p_name,\n            es.time_in,\n            es.time_out,\n            ea.checktime_in,\n            ea.checktime_out,\n            ea.state,\n            u.username,\n            ea.reg_date\n        FROM employee_attendance ea\n        JOIN employee_scheduale es ON ea.emp_sch_id = es.emp_sch_id\n        JOIN employee emp ON es.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN user_branch ub ON ea.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY ea.emp_att_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            ea.emp_att_id,\n            p.p_name,\n            es.time_in,\n            es.time_out,\n            ea.checktime_in,\n            ea.checktime_out,\n            ea.state,\n            u.username,\n            ea.reg_date\n        FROM employee_attendance ea\n        JOIN employee_scheduale es ON ea.emp_sch_id = es.emp_sch_id\n        JOIN employee emp ON es.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN user_branch ub ON ea.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY ea.emp_att_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.employee_schedule_show(p_branch_id integer)\n RETURNS TABLE(emp_sch_id integer, employee_name character varying, time_in time without time zone, time_out time without time zone, day_name character varying, shift_name character varying, state character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            es.emp_sch_id,\n            p.p_name,\n            es.time_in,\n            es.time_out,\n            d.day,\n            sh.shift,\n            es.state,\n            u.username,\n            es.reg_date\n        FROM employee_scheduale es\n        JOIN employee emp ON es.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN day d ON es.day_id = d.d_id\n        JOIN shift sh ON es.sh_id = sh.sh_id\n        JOIN user_branch ub ON es.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY es.emp_sch_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            es.emp_sch_id,\n            p.p_name,\n            es.time_in,\n            es.time_out,\n            d.day,\n            sh.shift,\n            es.state,\n            u.username,\n            es.reg_date\n        FROM employee_scheduale es\n        JOIN employee emp ON es.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN day d ON es.day_id = d.d_id\n        JOIN shift sh ON es.sh_id = sh.sh_id\n        JOIN user_branch ub ON es.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY es.emp_sch_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.employee_show(p_branch_id integer)\n RETURNS TABLE(tt_id integer, person_name character varying, phone_number character varying, salary numeric, location character varying, person_type character varying, username character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Return employee details for a specific branch\n    RETURN QUERY\n    SELECT \n        em.tt_id,\n        p.p_name AS person_name,\n        p.tel AS phone_number,\n        em.salary,\n        CONCAT(ad.district, ' - ', ad.village) AS location,  -- Concatenate district and village\n        p.p_type AS person_type,\n        u.username\n    FROM \n        people p\n    JOIN \n        employee em ON em.p_id = p.p_id\n    JOIN \n        address ad ON ad.add_id = p.ad_id\n    JOIN \n        user_branch ub ON ub.u_br_id = p.u_br_id\n    JOIN \n        users u ON u.usr_id = ub.usr_id\n    WHERE \n        em.br_id = p_branch_id  -- Filter by branch ID\n    ORDER BY \n        p.p_name;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.employee_vocation_show(p_branch_id integer)\n RETURNS TABLE(emp_voc_id integer, employee_name character varying, vocation_date date, vocation_type character varying, description character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            ev.emp_voc_id,\n            p.p_name,\n            ev.voc_date,\n            ev.type,\n            ev.description,\n            u.username,\n            ev.reg_date\n        FROM employee_vocation ev\n        JOIN employee emp ON ev.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN user_branch ub ON ev.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY ev.emp_voc_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            ev.emp_voc_id,\n            p.p_name,\n            ev.voc_date,\n            ev.type,\n            ev.description,\n            u.username,\n            ev.reg_date\n        FROM employee_vocation ev\n        JOIN employee emp ON ev.emp_id = emp.emp_id\n        JOIN people p ON emp.p_id = p.p_id\n        JOIN user_branch ub ON ev.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY ev.emp_voc_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.event_show()\n RETURNS TABLE(ev_id integer, event_name character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Return all events from the event table\n    RETURN QUERY\n    SELECT \n        e.ev_id,\n        e.event\n    FROM \n        event e\n    ORDER BY \n        e.ev_id;  -- Optional: Orders by event ID\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_attendance_show(p_branch_id integer)\n RETURNS TABLE(ex_t_id integer, student_name character varying, class character varying, exam character varying, attendance_status character varying, room_name character varying, subject character varying, reason text, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n       SELECT \n            ea.ex_t_id,\n            p.p_name,\n            cl.class,\n            e.exam,\n            sta.state,\n            r.room_name,\n            sub.name,\n            ea.reason,\n            u.username,\n            ea.reg_date\n        FROM exam_attendance ea\n        JOIN student_class sc ON ea.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN exam_reg er ON ea.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN state_attendance sta ON ea.st_att_id = sta.st_att_id\n        JOIN rooms r ON  r.r_id = ea.ro_id\n        JOIN subjects sub ON  sub.sub_id = ea.su_id\n        JOIN user_branch ub ON ea.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY ea.ex_t_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            ea.ex_t_id,\n            p.p_name,\n            cl.class,\n            e.exam,\n            sta.state,\n            r.room_name,\n            sub.name,\n            ea.reason,\n            u.username,\n            ea.reg_date\n        FROM exam_attendance ea\n        JOIN student_class sc ON ea.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN exam_reg er ON ea.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN state_attendance sta ON ea.st_att_id = sta.st_att_id\n        JOIN rooms r ON  r.r_id = ea.ro_id\n        JOIN subjects sub ON  sub.sub_id = ea.su_id\n        JOIN user_branch ub ON ea.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY ea.ex_t_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_reg_show(p_branch_id integer)\n RETURNS TABLE(ex_reg_id integer, exam character varying, academic_name character varying, exam_type character varying, start_date date, end_date date, deadline date, exam_status character varying, username character varying, reg_date character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all levels\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT \n            er.ex_reg_id,\n            e.exam,\n            a.academic_name,\n            er.exam_type,\n            er.start_date,\n            er.end_date,\n            er.deadline,\n            er.exam_status,\n            u.username,\n            TO_CHAR(e.reg_date, 'DD-Mon-YYYY HH24:MI')::VARCHAR  -- CAST timestamp to varchar\n        FROM exam_reg er \n        JOIN academic_year a ON a.a_y_id = er.a_y_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN user_branch ub ON ub.u_br_id = er.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        ORDER BY er.ex_reg_id;\n\n    ELSE\n        -- Return levels for a specific branch\n        RETURN QUERY\n        SELECT \n            er.ex_reg_id,\n            e.exam,\n            a.academic_name,\n            er.exam_type,\n            er.start_date,\n            er.end_date,\n            er.deadline,\n            er.exam_status,\n            u.username,\n            TO_CHAR(e.reg_date, 'DD-Mon-YYYY HH24:MI')::VARCHAR  -- CAST timestamp to varchar\n        FROM exam_reg er \n        JOIN academic_year a ON a.a_y_id = er.a_y_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN user_branch ub ON ub.u_br_id = er.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE ub.br_id = p_branch_id  -- WHERE clause fixed\n        ORDER BY er.ex_reg_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_schedule_show(p_branch_id integer)\n RETURNS TABLE(ex_s_id integer, day character varying, period character varying, subject character varying, shift character varying, class character varying, exam character varying, start_time time without time zone, end_time time without time zone, exam_date date, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all records\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT \n            exs.ex_s_id,\n            d.day,\n            pr.period,\n            sub.name,\n            sh.shift,\n            cl.class,\n            e.exam,\n            exs.start_time,\n            exs.end_time,\n            exs.exam_date,\n            u.username,\n            exs.reg_date\n        FROM exam_schedule exs \n        JOIN day d ON exs.d_id = d.d_id \n        JOIN period pr ON pr.pr_id = exs.pr_id \n        JOIN shift sh ON sh.sh_id = exs.sh_id \n        JOIN class cl ON exs.cl_id = cl.cl_id\n        JOIN exam_reg er ON er.ex_reg_id = exs.ex_r_id \n        JOIN subject_class subcl ON subcl.sub_cl_id = exs.sub_cl_id \n        JOIN subjects sub ON sub.sub_id = subcl.sub_id \n        JOIN exam e ON e.ex_id = er.ex_id  \n        JOIN user_branch ub ON ub.u_br_id = exs.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        ORDER BY exs.exam_date, exs.start_time;\n\n    ELSE\n        -- Return records for specific branch\n        RETURN QUERY\n        SELECT \n            exs.ex_s_id,\n            d.day,\n            pr.period,\n            sub.name,\n            sh.shift,\n            cl.class,\n            e.exam,\n            exs.start_time,\n            exs.end_time,\n            exs.exam_date,\n            u.username,\n            exs.reg_date\n        FROM exam_schedule exs \n        JOIN day d ON exs.d_id = d.d_id \n        JOIN period pr ON pr.pr_id = exs.pr_id \n        JOIN shift sh ON sh.sh_id = exs.sh_id \n        JOIN class cl ON exs.cl_id = cl.cl_id\n        JOIN exam_reg er ON er.ex_reg_id = exs.ex_r_id \n        JOIN subject_class subcl ON subcl.sub_cl_id = exs.sub_cl_id \n        JOIN subjects sub ON sub.sub_id = subcl.sub_id \n        JOIN exam e ON e.ex_id = er.ex_id  \n        JOIN user_branch ub ON ub.u_br_id = exs.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE ub.br_id = p_branch_id  -- Missing WHERE clause in your code!\n        ORDER BY exs.exam_date, exs.start_time;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_show(br_id_sp integer)\n RETURNS TABLE(id text, exam text, ordering text, date text)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name FROM branch b  WHERE b.br_id = br_id_sp;\n    \n    -- Check if it's "All" branch\n    IF var_branch_name = 'All' THEN \n        \n        -- Return all exams (no branch filter)\n        RETURN QUERY\n        SELECT \n            e.ex_id::TEXT as ID,\n            e.exam::TEXT as Exam,\n            e.ordering::TEXT as Ordering,\n            DATE(e.reg_date)::TEXT as Date\n        FROM exam e\n        INNER JOIN user_branch ub ON e.u_br_id = ub.u_br_id\n        INNER JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY e.ex_id;\n        \n    ELSE \n        -- Return exams for specific branch\n        RETURN QUERY\n        SELECT \n            e.ex_id::TEXT as ID,\n            e.exam::TEXT as Exam,\n            e.ordering::TEXT as Ordering,\n            DATE(e.reg_date)::TEXT as Date\n        FROM exam e\n        INNER JOIN user_branch ub ON e.u_br_id = ub.u_br_id\n        INNER JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = br_id_sp\n        ORDER BY e.ex_id;\n       \n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_siting_show(p_branch_id integer)\n RETURNS TABLE(ex_set_id integer, academic_name character varying, percentage_fail_pass numeric, attendance_marks numeric, activity_marks numeric, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all levels\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT \n            e.ex_set_id,\n            a.academic_name,\n            e.percentage_fail_pass,\n            e.attendance_marks,\n            e.activity_marks,\n\t\t\tu.username,\n            DATE(e.reg_date)  -- Ensure it's DATE, not TIMESTAMP\n        FROM exam_siting e \n        JOIN academic_year a ON a.a_y_id = e.a_y_id \n        JOIN user_branch ub ON ub.u_br_id = e.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        ORDER BY e.ex_set_id;\n\n    ELSE\n        -- Return levels for a specific branch\n        RETURN QUERY\n        SELECT \n            e.ex_set_id,\n            a.academic_name,\n            e.percentage_fail_pass,\n            e.attendance_marks,\n            e.activity_marks,\n\t\t\tu.username,\n            DATE(e.reg_date)\n        FROM exam_siting e \n        JOIN academic_year a ON a.a_y_id = e.a_y_id \n        JOIN user_branch ub ON ub.u_br_id = e.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY e.ex_set_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.exam_time_show(p_branch_id integer)\n RETURNS TABLE(ex_t_id integer, question_id integer, start_time time without time zone, end_time time without time zone, state character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            et.ex_t_id,\n            qt.q_no,\n            et.start_time,\n            et.end_time,\n            et.state,\n            u.username,\n            et.reg_date\n        FROM exam_time et\n        JOIN question_type qt ON et.q_no = qt.q_no\n        JOIN user_branch ub ON et.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY et.ex_t_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            et.ex_t_id,\n            qt.q_no,\n            et.start_time,\n            et.end_time,\n            et.state,\n            u.username,\n            et.reg_date\n        FROM exam_time et\n        JOIN question_type qt ON et.q_no = qt.q_no\n        JOIN user_branch ub ON et.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY et.ex_t_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.expense_budget_show(p_branch_id integer)\n RETURNS TABLE(exp_pud_id integer, expense_name character varying, description character varying, amount numeric, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            eb.exp_pud_id,\n            e.name Expense,\n            eb.description,\n            eb.amount,\n            u.username,\n            eb.reg_date\n        FROM expense_budget eb\n        JOIN expense e ON eb.ex_id = e.ex_id\n        JOIN user_branch ub ON eb.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY eb.exp_pud_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            eb.exp_pud_id,\n            e.name Expense,\n            eb.description,\n            eb.amount,\n            u.username,\n            eb.reg_date\n        FROM expense_budget eb\n        JOIN expense e ON eb.ex_id = e.ex_id\n        JOIN user_branch ub ON eb.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY eb.exp_pud_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.expense_show(br_id_sp integer)\n RETURNS TABLE(id integer, name character varying, date timestamp without time zone, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n           select  ex.ex_id ID , ex.name ,ex.reg_date Date, u.username from  expense ex\n\t\t\t\tJOIN user_branch ub on ub.u_br_id = ex.u_br_id\n\t\t\t\tJOIN branch b on b.br_id = ex.br_id\n\t\t\t\tJOIN users  u on u.usr_id = ub.usr_id;\n\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n        select  ex.ex_id ID , ex.name ,ex.reg_date Date, u.username from  expense ex\n\t\t\tJOIN user_branch ub on ub.u_br_id = ex.u_br_id\n\t\t\tJOIN branch b on b.br_id = ex.br_id\n\t\t\tJOIN users  u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.finance_appointment_show(p_branch_id integer)\n RETURNS TABLE(f_o_id integer, responsible_person character varying, comment character varying, state character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            fa.f_ap_id,\n            p.p_name Resopneiple,\n            fa.comment,\n            fa.state,\n            u.username,\n            fa.reg_date\n        FROM finance_apoint fa\n        JOIN responsible r ON fa.res_id = r.res_id\n\t\tjoin people p on p.p_id = r.p_id\n        JOIN user_branch ub ON fa.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY fa.f_ap_id;\n    ELSE\n        RETURN QUERY\n         SELECT \n            fa.f_ap_id,\n            p.p_name Resopneiple,\n            fa.comment,\n            fa.state,\n            u.username,\n            fa.reg_date\n        FROM finance_apoint fa\n        JOIN responsible r ON fa.res_id = r.res_id\n\t\tjoin people p on p.p_id = r.p_id\n        JOIN user_branch ub ON fa.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY fa.f_ap_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.job_show()\n RETURNS TABLE(j_id integer, j_name character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Return all jobs without branch filtering\n    RETURN QUERY\n    SELECT \n        j.j_id,\n        j.j_name\n    FROM \n        job j\n    ORDER BY \n        j.j_id;  -- Optional: Orders by job ID\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.lesson_activity_show(p_branch_id integer)\n RETURNS TABLE("ID" integer, "Activity_Type" character varying, "Class" character varying, "Subject" character varying, "Marks" character varying, "Description" text, "Exam" character varying, "Created_By" character varying, "Date" character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            l.ac_t_id,\n            ac.type,\n            cl.class,\n            sub.name,\n            l.marks::VARCHAR,  -- Explicit cast to VARCHAR\n            l.description,\n            e.exam,\n            u.username,\n            TO_CHAR(l.reg_date, 'DD/MM/YYYY')::VARCHAR\n        FROM lesson_activity l \n        JOIN activity_type ac ON ac.ac_id = l.ac_id \n        JOIN class cl ON l.cl_id = cl.cl_id \n        JOIN subject_class subcl ON subcl.sub_cl_id = l.sub_cl_id \n        JOIN subjects sub ON sub.sub_id = subcl.sub_id \n        JOIN exam_reg er ON er.ex_reg_id = l.e_r_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN user_branch ub ON ub.u_br_id = l.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        ORDER BY l.ac_t_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            l.ac_t_id,\n            ac.type,\n            cl.class,\n            sub.name,\n            l.marks::VARCHAR,  -- Explicit cast to VARCHAR\n            l.description,\n            e.exam,\n            u.username,\n            TO_CHAR(l.reg_date, 'DD/MM/YYYY')::VARCHAR\n        FROM lesson_activity l \n        JOIN activity_type ac ON ac.ac_id = l.ac_id \n        JOIN class cl ON l.cl_id = cl.cl_id \n        JOIN subject_class subcl ON subcl.sub_cl_id = l.sub_cl_id \n        JOIN subjects sub ON sub.sub_id = subcl.sub_id \n        JOIN exam_reg er ON er.ex_reg_id = l.e_r_id \n        JOIN exam e ON e.ex_id = er.ex_id \n        JOIN user_branch ub ON ub.u_br_id = l.u_br_id \n        JOIN users u ON u.usr_id = ub.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY l.ac_t_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.levels_show(p_branch_id integer)\n RETURNS TABLE(lev_id integer, l_ty_id integer, level character varying, fee numeric, level_name character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        SELECT l.lev_id, l.l_ty_id, l.level, l.fee, lt.name\n        FROM levels l\n        JOIN level_type lt ON lt.l_ty_id = l.l_ty_id\n        ORDER BY l.lev_id;\n    ELSE\n        RETURN QUERY\n        SELECT l.lev_id, l.l_ty_id, l.level, l.fee, lt.name\n        FROM levels l\n        JOIN level_type lt ON lt.l_ty_id = l.l_ty_id\n        JOIN branch br ON l.br_id = br.br_id\n        WHERE l.br_id = p_branch_id\n        ORDER BY l.lev_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.meeting_agenda_show(p_branch_id integer)\n RETURNS TABLE(m_ag_id integer, agenda text, participance text, comments text, decisions text, meet_date date, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            ma.m_ag_id,\n            ma.agenda,\n            ma.participance,\n            ma.comments,\n            ma.decisions,\n            ma.meet_date,\n            u.username,\n            ma.reg_date\n        FROM meeting_agenda ma\n        JOIN user_branch ub ON ma.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY ma.m_ag_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            ma.m_ag_id,\n            ma.agenda,\n            ma.participance,\n            ma.comments,\n            ma.decisions,\n            ma.meet_date,\n            u.username,\n            ma.reg_date\n        FROM meeting_agenda ma\n        JOIN user_branch ub ON ma.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY ma.m_ag_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.money_methods_show(br_id_sp integer)\n RETURNS TABLE(id integer, method character varying, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                 select  mm.mm_id ID , mm.method , u.username from money_methods mm\n\t\t\t\t\tjoin user_branch ub on ub.u_br_id = mm.u_br_id \n\t\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\t\tjoin  users u on u.usr_id = ub.usr_id;\n\t\t\t\t\n\t\t\t\t\t\t\t\t\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\t\n       select  mm.mm_id ID , mm.method , u.username from money_methods mm\n\t\t\t\tjoin user_branch ub on ub.u_br_id = mm.u_br_id \n\t\t\t\tjoin branch b on b.br_id = ub.br_id\n\t\t\t\tjoin  users u on u.usr_id = ub.usr_id\n\t\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.note_payable_show(p_branch_id integer)\n RETURNS TABLE(cust_dep_id integer, person_name character varying, account_name character varying, amount numeric, interest_rate numeric, note_type character varying, description character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            np.note_pay_id,\n            p.p_name,\n            a.acc_name,\n            np.amount,\n            np.rate,\n            np.type,\n            np.description,\n            u.username,\n            np.reg_date\n        FROM note_payable np\n        JOIN people p ON np.p_id = p.p_id\n        JOIN accounts a ON np.acc_id = a.acc_id\n        JOIN user_branch ub ON np.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY np.note_pay_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            np.note_pay_id,\n            p.p_name,\n            a.acc_name,\n            np.amount,\n            np.rate,\n            np.type,\n            np.description,\n            u.username,\n            np.reg_date\n        FROM note_payable np\n        JOIN people p ON np.p_id = p.p_id\n        JOIN accounts a ON np.acc_id = a.acc_id\n        JOIN user_branch ub ON np.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY np.note_pay_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.other_income_show(br_id_sp integer)\n RETURNS TABLE(id integer, "income name" character varying, amount numeric, description character varying, reciever_phone character varying, accounts character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                SELECT oi.ot_in_id ID, income_name "income name" , oi.amount , oi.description , oi.reciever_phone, acc_name accounts , u.username , oi.reg_Date from other_income oi\n\t\t\t\tJOIN accounts ac on ac.acc_id = oi.acc_id\n\t\t\t\tJOIN user_branch  ub on ub.u_br_id = oi.u_br_id \n\t\t\t\tJOIN  branch b on  b.br_id = ub.br_id\n\t\t\t\tJOIN  users  u on u.usr_id = ub.usr_id;\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\n\t\t\n        SELECT oi.ot_in_id ID, income_name "income name" , oi.amount , oi.description , oi.reciever_phone, acc_name accounts, u.username , oi.reg_Date from other_income oi\n\t\t\tJOIN accounts ac on ac.acc_id = oi.acc_id\n\t\t\tJOIN user_branch  ub on ub.u_br_id = oi.u_br_id \n\t\t\tJOIN  branch b on  b.br_id = ub.br_id\n\t\t\tJOIN  users  u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.profit_sharing_show(p_branch_id integer)\n RETURNS TABLE(pr_sh_id integer, person_name character varying, close_date timestamp without time zone, start_date timestamp without time zone, amount numeric, new_investment numeric, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            ps.pr_sh_id,\n            p.p_name,\n            c.close_date,\n\t\t\tc.start_date,\n            ps.amount,\n            ps.new_investment,\n            u.username,\n            ps.reg_date\n        FROM profit_sharing ps\n        JOIN people p ON ps.p_id = p.p_id\n        JOIN closing c ON c.cl_id = ps.cl_id\n        JOIN user_branch ub ON ps.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY ps.pr_sh_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            ps.pr_sh_id,\n            p.p_name,\n            c.close_date,\n\t\t\tc.start_date,\n            ps.amount,\n            ps.new_investment,\n            u.username,\n            ps.reg_date\n        FROM profit_sharing ps\n        JOIN people p ON ps.p_id = p.p_id\n        JOIN closing c ON c.cl_id = ps.cl_id\n        JOIN user_branch ub ON ps.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY ps.pr_sh_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.question_category_show(p_branch_id integer)\n RETURNS TABLE(q_cat_id integer, category character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n   \n        RETURN QUERY\n        select q.q_cat_id ID,q.category from question_category q;\n \nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.question_type_show(p_branch_id integer)\n RETURNS TABLE(q_no integer, subject_name character varying, class_name character varying, chapters character varying, total_questions integer, total_marks numeric, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            qt.q_no,\n            sub.name,\n            cl.class,\n            qt.chapters,\n            qt.total,\n            qt.total_mark,\n            u.username,\n            qt.reg_date\n        FROM question_type qt\n        JOIN subject_class sc ON qt.su_cl_id = sc.sub_cl_id\n        JOIN subjects sub ON sc.sub_id = sub.sub_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN user_branch ub ON qt.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY qt.q_no;\n    ELSE\n        RETURN QUERY\n        SELECT \n            qt.q_no,\n            sub.name,\n            cl.class,\n            qt.chapters,\n            qt.total,\n            qt.total_mark,\n            u.username,\n            qt.reg_date\n        FROM question_type qt\n        JOIN subject_class sc ON qt.su_cl_id = sc.sub_cl_id\n        JOIN subjects sub ON sc.sub_id = sub.sub_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN user_branch ub ON qt.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY qt.q_no;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.questions_show(p_branch_id integer)\n RETURNS TABLE(q_id integer, grade_name character varying, subject_name character varying, chapter_name character varying, chapter_page character varying, question_category character varying, question_name text, marks numeric, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            q.q_id,\n            gr.grade_name,\n            sub.name,\n            c.chapter,\n            q.chapter_page,\n            qc.category,\n            q.q_name,\n            q.marks,\n            u.username,\n            q.reg_date\n        FROM questions q\n        JOIN grade gr ON q.gr_id = gr.gr_id\n        JOIN subjects sub ON q.su_id = sub.sub_id\n        JOIN chapters c ON q.chap_id = c.chap_id\n        JOIN question_category qc ON q.q_cat_id = qc.q_cat_id\n        JOIN user_branch ub ON q.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY q.q_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            q.q_id,\n            gr.grade_name,\n            sub.name,\n            c.chapter,\n            q.chapter_page,\n            qc.category,\n            q.q_name,\n            q.marks,\n            u.username,\n            q.reg_date\n        FROM questions q\n        JOIN grade gr ON q.gr_id = gr.gr_id\n        JOIN subjects sub ON q.su_id = sub.sub_id\n        JOIN chapters c ON q.chap_id = c.chap_id\n        JOIN question_category qc ON q.q_cat_id = qc.q_cat_id\n        JOIN user_branch ub ON q.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY q.q_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.receipt_show(br_id_sp integer)\n RETURNS TABLE(no integer, "Charge No" integer, reg_date timestamp without time zone, transactions character varying, academic character varying, balance_text character varying, description character varying, account character varying, paid numeric)\n LANGUAGE plpgsql\nAS $function$\nDECLARE \n    transfer_br_id_sp TEXT;\nBEGIN\n    -- Retrieve branch name based on the provided branch ID\n    SELECT b.br_name INTO transfer_br_id_sp   FROM branch b  WHERE b.br_id = br_id_sp;\n\n    -- If branch name is 'All', return all account transfers\n    IF transfer_br_id_sp = 'All' THEN\n        RETURN QUERY\n\t\t\n                SELECT  r.r_id No , ch.ch_id  "Charge No" , r.reg_date Transactions , ay.academic_name Academic , r.balance_text  Description ,  ac.acc_name Account , r.amount Paid from receipt r \n\t\t\t\t\tJOIN  charge ch on ch.ch_id = r.ch_id JOIN student_class sc on sc.std_cl_id = ch.std_cl_id\n\t\t\t\t\tJOIN student s on s.std_id = sc.std_id JOIN people p on p.p_id = s.p_id \n\t\t\t\t\tJOIN accounts ac on ac.acc_id = r.acc_id JOIN academic_year ay on ay.a_y_id = sc.a_y_id\n\t\t\t\t\tJOIN user_branch ub on ub.u_br_id = r.r_id JOIN branch  b on b.br_id = ub.br_id\n\t\t\t\t\tJOIN users u on u.usr_id = ub.usr_id;\n    \n    ELSE\n        -- If branch name is not 'All', return account transfers for the given branch\n        RETURN QUERY\n\t\t\n        SELECT  r.r_id No , ch.ch_id  "Charge No" , r.reg_date Transactions , ay.academic_name Academic , r.balance_text  Description ,  ac.acc_name Account , r.amount Paid from receipt r \n\t\tJOIN  charge ch on ch.ch_id = r.ch_id JOIN student_class sc on sc.std_cl_id = ch.std_cl_id\n\t\tJOIN student s on s.std_id = sc.std_id JOIN people p on p.p_id = s.p_id \n\t\tJOIN accounts ac on ac.acc_id = r.acc_id JOIN academic_year ay on ay.a_y_id = sc.a_y_id\n\t\tJOIN user_branch ub on ub.u_br_id = r.r_id JOIN branch  b on b.br_id = ub.br_id\n\t\tJOIN users u on u.usr_id = ub.usr_id\n\t\t\twhere b.br_id=br_id_sp;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.responsible_with_no_student_show()\n RETURNS TABLE(result text, id integer, responsiple text, phone_one text, phone_two text)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    v_res_count BIGINT := 0;\nBEGIN\n    SELECT COUNT(r.res_id)\n    INTO v_res_count\n    FROM responsible r\n    WHERE NOT EXISTS (\n        SELECT 1\n        FROM student s\n        WHERE s.res_id = r.res_id\n    );\n\n    IF v_res_count > 0 THEN\n        RETURN QUERY\n        SELECT\n            NULL::TEXT AS result,\n            r.res_id AS id,\n            p.p_name::TEXT AS responsiple,\n            p.tel::TEXT AS phone_one,\n            r.phone::TEXT AS phone_two\n        FROM responsible r\n        LEFT JOIN people p ON p.p_id = r.p_id\n        WHERE NOT EXISTS (\n            SELECT 1\n            FROM student s\n            WHERE s.res_id = r.res_id\n        );\n    ELSE\n        RETURN QUERY\n        SELECT\n            COALESCE((SELECT a.body::TEXT FROM alerts a WHERE LOWER(a.title) = 'notfound' LIMIT 1), 'Not found') AS result,\n            NULL::INT,\n            NULL::TEXT,\n            NULL::TEXT,\n            NULL::TEXT;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.result_show(p_branch_id integer)\n RETURNS TABLE(r_id integer, student_name character varying, class character varying, exam character varying, subject character varying, marks numeric, activity numeric, approve_status character varying, lock_status character varying, recorded_by character varying, approved_by character varying, edited_by character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            r.r_id,\n            p.p_name,\n            cl.class,\n            e.exam,\n            sub.name,\n            r.marks,\n            r.activity,\n            r.approve,\n            r.lock,\n            u1.username,\n            u2.username,\n            u3.username,\n            r.reg_date\n        FROM result r\n        JOIN student_class sc ON r.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN exam_reg er ON r.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN subjects sub ON r.su_id = sub.sub_id\n        JOIN user_branch ub ON r.u_br_id = ub.u_br_id\n        JOIN users u1 ON ub.usr_id = u1.usr_id\n        LEFT JOIN users u2 ON r.approved_user = u2.usr_id\n        LEFT JOIN users u3 ON r.editted_user = u3.usr_id\n        ORDER BY r.r_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            r.r_id,\n            p.p_name,\n            cl.class,\n            e.exam,\n            sub.name,\n            r.marks,\n            r.activity,\n            r.approve,\n            r.lock,\n            u1.username,\n            u2.username,\n            u3.username,\n            r.reg_date\n        FROM result r\n        JOIN student_class sc ON r.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN exam_reg er ON r.e_r_id = er.ex_reg_id\n        JOIN exam e ON er.ex_id = e.ex_id\n        JOIN subjects sub ON r.su_id = sub.sub_id\n        JOIN user_branch ub ON r.u_br_id = ub.u_br_id\n        JOIN users u1 ON ub.usr_id = u1.usr_id\n        LEFT JOIN users u2 ON r.approved_user = u2.usr_id\n        LEFT JOIN users u3 ON r.editted_user = u3.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY r.r_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.rooms_show(p_branch_id integer)\n RETURNS TABLE(r_id integer, room_name character varying, no_of_students integer, no_of_teachers integer, username character varying)\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    var_branch_name TEXT;\nBEGIN\n    -- Get branch name\n    SELECT b.br_name INTO var_branch_name \n    FROM branch b \n    WHERE b.br_id = p_branch_id;\n\n    -- If branch name is 'All', return all levels\n    IF var_branch_name = 'All' THEN\n        RETURN QUERY\n        select r.r_id ID,r.room_name Room,r.no_of_students "No of Students",r.no_of_teachers "No of Teachers",u.username from rooms r join user_branch ub on ub.u_br_id = r.u_br_id join users u on  u.usr_id = ub.usr_id;\n\n    ELSE\n        -- Return levels for a specific branch\n        RETURN QUERY\n        select r.r_id ID,r.room_name Room,r.no_of_students "No of Students",r.no_of_teachers "No of Teachers",u.username from rooms r join user_branch ub on ub.u_br_id = r.u_br_id join users u on  u.usr_id = ub.usr_id and ub.br_id=p_branch_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.send_notices_show(p_branch_id integer)\n RETURNS TABLE(not_id integer, notice_title character varying, notice_body character varying, start_date date, end_date date, state character varying, schedule_notice character varying, is_change boolean, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            sn.not_id,\n            sn.notice_title,\n            sn.notice_body,\n            sn.start_date,\n            sn.end_date,\n            sn.state,\n            sn.schedule_notice,\n            sn.ischange,\n            u.username,\n            sn.reg_date\n        FROM send_notices sn\n        JOIN user_branch ub ON sn.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY sn.not_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            sn.not_id,\n            sn.notice_title,\n            sn.notice_body,\n            sn.start_date,\n            sn.end_date,\n            sn.state,\n            sn.schedule_notice,\n            sn.ischange,\n            u.username,\n            sn.reg_date\n        FROM send_notices sn\n        JOIN user_branch ub ON sn.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY sn.not_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.student_attendance_show(p_branch_id integer)\n RETURNS TABLE(std_att_id integer, student_name character varying, class_name character varying, period_name character varying, reason text, attendance_status character varying, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            sa.std_att_id,\n            p.p_name,\n            cl.class,\n            pr.period,\n            sa.reason,\n            sta.state,\n            u.username,\n            sa.reg_date\n        FROM student_attendance sa\n        JOIN student_class sc ON sa.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN period pr ON sa.pr_id = pr.pr_id\n        JOIN state_attendance sta ON sa.st_att_id = sta.st_att_id\n        JOIN user_branch ub ON sa.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY sa.std_att_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            sa.std_att_id,\n            p.p_name,\n            cl.class,\n            pr.period,\n            sa.reason,\n            sta.state,\n            u.username,\n            sa.reg_date\n        FROM student_attendance sa\n        JOIN student_class sc ON sa.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN period pr ON sa.pr_id = pr.pr_id\n        JOIN state_attendance sta ON sa.st_att_id = sta.st_att_id\n        JOIN user_branch ub ON sa.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id and ub.br_id=p_branch_id\n        ORDER BY sa.std_att_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.sub_questions_show(p_branch_id integer)\n RETURNS TABLE(sub_q_id integer, question_name text, sub_question_title text, state character varying, username character varying, reg_date timestamp without time zone)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            sq.sub_q_id,\n            q.q_name,\n            sq.sub_question_title,\n            sq.state,\n            u.username,\n            sq.reg_date\n        FROM sub_questions sq\n        JOIN questions q ON sq.q_id = q.q_id\n        JOIN user_branch ub ON sq.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY sq.sub_q_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            sq.sub_q_id,\n            q.q_name,\n            sq.sub_question_title,\n            sq.state,\n            u.username,\n            sq.reg_date\n        FROM sub_questions sq\n        JOIN questions q ON sq.q_id = q.q_id\n        JOIN user_branch ub ON sq.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY sq.sub_q_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.subject_class_show(br_id_sp integer, cl_id_sp integer, a_y_id_sp integer)\n RETURNS TABLE(sub_cl_id integer, cl_id integer, academic_name character varying, class_name character varying, sub_id integer, subject_name character varying, emp_id integer, employee_name character varying, no_of_period integer, state character varying, u_br_id integer, reg_date date, a_y_id integer)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT \n        sc.sub_cl_id::integer,\n        sc.cl_id::integer,\n\t\tac.academic_name::varchar,\n        cl.class::varchar,\n        sc.sub_id::integer,\n        s.name::varchar,\n        sc.emp_id::integer,\n        p.p_name::varchar AS employee_name,\n        sc.no_of_period::integer,\n        sc.state::varchar,\n        sc.u_br_id::integer,\n        sc.reg_date::date,\n        sc.a_y_id::integer\n    FROM subjects s\n    JOIN subject_class sc ON s.sub_id = sc.sub_id\n    JOIN class cl ON sc.cl_id = cl.cl_id\n    JOIN employee em ON em.emp_id = sc.emp_id\n    JOIN people p ON p.p_id = em.p_id\n\tjoin academic_year ac on ac.a_y_id = sc.a_y_id\n    WHERE cl.br_id = br_id_sp\n      AND sc.cl_id = cl_id_sp\n      AND sc.a_y_id = a_y_id_sp\n\t  \n    ORDER BY sc.sub_cl_id DESC;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.subjects_show()\n RETURNS TABLE(id integer, name character varying, ordering integer)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    RETURN QUERY\n    SELECT\n        s.sub_id as ID,\n        s.name,\n        s.ordering\n    FROM subjects s;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.title_show()\n RETURNS TABLE(tt_id integer, title_name character varying)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Return all titles from the title table\n    RETURN QUERY\n    SELECT \n        t.tt_id,\n        t.title\n    FROM \n        title t\n    ORDER BY \n        t.tt_id;  -- Optional: Orders by title ID\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.transcript_show(p_branch_id integer)\n RETURNS TABLE(tr_id integer, serial_number character varying, student_name character varying, class_name character varying, description text, issue_date date, username character varying, reg_date date)\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Handle "All" branches (assuming 0 means All)\n    IF p_branch_id = 0 THEN\n        RETURN QUERY\n        SELECT \n            t.tr_id,\n            t.serial_number,\n            p.p_name,\n            cl.class,\n            t.description,\n            t.ishue_date,\n            u.username,\n            t.reg_date\n        FROM transcript t\n        JOIN student_class sc ON t.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN user_branch ub ON t.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        ORDER BY t.tr_id;\n    ELSE\n        RETURN QUERY\n        SELECT \n            t.tr_id,\n            t.serial_number,\n            p.p_name,\n            cl.class,\n            t.description,\n            t.ishue_date,\n            u.username,\n            t.reg_date\n        FROM transcript t\n        JOIN student_class sc ON t.std_cl_id = sc.std_cl_id\n        JOIN student s ON sc.std_id = s.std_id\n        JOIN people p ON s.p_id = p.p_id\n        JOIN class cl ON sc.cl_id = cl.cl_id\n        JOIN user_branch ub ON t.u_br_id = ub.u_br_id\n        JOIN users u ON ub.usr_id = u.usr_id\n        WHERE ub.br_id = p_branch_id\n        ORDER BY t.tr_id;\n    END IF;\nEND;\n$function$\n;\n
CREATE OR REPLACE FUNCTION public.users_show(p_br_id integer)\n RETURNS TABLE(usr_id integer, p_id integer, p_name character varying, username character varying, password character varying, br_id integer, br_name text, state character varying, lock_user character varying, privalage jsonb, reg_date timestamp without time zone)\n LANGUAGE sql\nAS $function$\n    SELECT\n        u.usr_id::INTEGER,\n        u.p_id::INTEGER,\n        p.p_name::VARCHAR,\n        u.username::VARCHAR,\n        u.password::VARCHAR,\n        MIN(ub.br_id)::INTEGER AS br_id,\n        string_agg(DISTINCT b.br_name::TEXT, ', ' ORDER BY b.br_name::TEXT) AS br_name,\n        u.state::VARCHAR,\n        u.lock_user::VARCHAR,\n        COALESCE(jsonb_agg(DISTINCT ub.privalage) FILTER (WHERE ub.privalage IS NOT NULL), '[]'::jsonb) AS privalage,\n        u.reg_date::TIMESTAMP\n    FROM users u\n    LEFT JOIN people p \n        ON p.p_id = u.p_id\n    LEFT JOIN user_branch ub \n        ON ub.usr_id = u.usr_id\n    LEFT JOIN branch b \n        ON b.br_id = ub.br_id\n    WHERE\n        (\n            EXISTS (\n                SELECT 1\n                FROM branch br\n                WHERE br.br_id = p_br_id\n                  AND br.br_name = 'All'\n            )\n        )\n        OR\n        (\n            ub.br_id = p_br_id\n        )\n    GROUP BY\n        u.usr_id,\n        u.p_id,\n        p.p_name,\n        u.username,\n        u.password,\n        u.state,\n        u.lock_user,\n        u.reg_date\n    ORDER BY u.usr_id;\n$function$\n;\n
